#!/usr/bin/env node
// sync-mesh-web.mjs — compile the web Agent Mesh's PURE logic modules into
// the app, so the native mesh runs the exact same layout / routing / review /
// card / HUD code as the web (ui/src/ui/views/agent-ops + lib/review-mesh).
//
//   node mobile/scripts/sync-mesh-web.mjs        (needs esbuild from the repo root)
//
// Output: mobile/src/lib/mesh/web-mesh.generated.js (checked in; do not edit).
import { build } from 'esbuild';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import fs from 'node:fs';

const here = path.dirname(fileURLToPath(import.meta.url));
const ui = path.resolve(here, '../../ui/src/ui');
const out = path.resolve(here, '../src/lib/mesh/web-mesh.generated.js');
const mods = [
  'views/agent-ops/iso/projection.ts',
  'views/agent-ops/iso/plugin-rooms.ts',
  'views/agent-ops/iso/agent-spread.ts',
  'views/agent-ops/iso/plugin-activity.ts',
  'views/agent-ops/hud-metrics.ts',
  'views/agent-ops/agent-hover-card.ts',
  'views/agent-ops/agent-hover-extras.ts',
  'lib/review-mesh/completed.ts',
  'lib/review-mesh/model.ts',
  'views/agent-ops/broadcast-director.ts',
  'views/agent-ops/iso/camera-director.ts',
  'components/world-interactions/world-state.ts',
];
const entry = mods.map((m) => `export * from ${JSON.stringify(path.join(ui, m))};`).join('\n');
const res = await build({
  stdin: { contents: entry, resolveDir: ui, loader: 'ts' },
  bundle: true,
  format: 'esm',
  target: 'es2019',
  platform: 'neutral',
  write: false,
  logLevel: 'warning',
  legalComments: 'none',
});
const banner = `// GENERATED by mobile/scripts/sync-mesh-web.mjs from the web Agent Mesh sources — do not edit.\n// ${mods.map((m) => `ui/src/ui/${m}`).join('\n// ')}\n/* eslint-disable */\n`;
fs.writeFileSync(out, banner + res.outputFiles[0].text.replaceAll(ui, 'ui/src/ui'));
console.log('wrote', path.relative(process.cwd(), out), fs.statSync(out).size, 'bytes');
